      return node === state.mostRecentlyFocusedNode;
    });
  });

  // If the currently focused is removed then browsers will move focus to the
  // <body> element. If this happens, try to move focus back into the trap.
  if (isFocusedNodeRemoved) {
    tryFocus(getInitialFocusNode());
  }
};
```

We can modify it to call updateTabbableNodes() before tryFocus.

But we must be careful not to cause infinite loops. updateTabbableNodes may be expensive but okay.

Thus edit: add `updateTabbableNodes();` before `tryFocus(getInitialFocusNode());`.

